   "file": "assets/adventures/dark-wizard/voice/m-led-7990445a.mp3",
   "text": "Led means showed the way. Rook led them.",
   "sha256": "c1086e1f00a89e48ff1e90aa55bb8b872c5e2444fa03748a63b6715c9738e6eb"
